// Filter deals that have been stalled for more than 7 days
const deals = $input.all();
const sevenDaysAgo = new Date();
sevenDaysAgo.setDate(sevenDaysAgo.getDate() - 7);

const stalledDeals = [];

for (const item of deals) {
  try {
    const deal = item.json;
    const lastModified = new Date(deal.properties?.hs_lastmodifieddate || deal.hs_lastmodifieddate);

    // Check if deal hasn't been touched in 7+ days
    if (lastModified < sevenDaysAgo) {
      stalledDeals.push({
        json: {
          dealId: deal.id,
          dealName: deal.properties?.dealname || deal.dealname || 'Unknown Deal',
          amount: deal.properties?.amount || deal.amount || 'Not specified',
          ownerId: deal.properties?.hubspot_owner_id || deal.hubspot_owner_id,
          lastModified: lastModified.toISOString(),
          daysSinceUpdate: Math.floor((new Date() - lastModified) / (1000 * 60 * 60 * 24)),
          closeDate: deal.properties?.closedate || deal.closedate
        }
      });
    }
  } catch (error) {
    // Skip deals with parsing errors
    continue;
  }
}

// Return stalled deals or empty indicator
if (stalledDeals.length === 0) {
  return [{ json: { noStalledDeals: true, message: 'No stalled deals found' } }];
}

return stalledDeals;

// Parse the OpenAI JSON response
const inputData = $input.first().json;
const contactData = $('HubSpot - Get Contact').first().json;
const dealData = $('Filter Stalled Deals (7+ Days)').first().json;

try {
  // Parse the message content (may be string or already parsed)
  let emailContent;
  const messageContent = inputData.message?.content || inputData.choices?.[0]?.message?.content;

  if (typeof messageContent === 'string') {
    emailContent = JSON.parse(messageContent);
  } else {
    emailContent = messageContent;
  }

  return [{
    json: {
      recipientEmail: contactData.properties?.email || '',
      recipientName: `${contactData.properties?.firstname || ''} ${contactData.properties?.lastname || ''}`.trim(),
      subject: emailContent.subject,
      body: emailContent.body,
      suggestedNextStep: emailContent.suggestedNextStep,
      dealId: dealData.dealId,
      dealName: dealData.dealName,
      dealAmount: dealData.amount,
      daysSinceUpdate: dealData.daysSinceUpdate,
      generatedAt: new Date().toISOString()
    }
  }];
} catch (error) {
  return [{
    json: {
      error: true,
      message: 'Failed to parse OpenAI response',
      rawResponse: inputData
    }
  }];
}

